import { config } from "dotenv";
import { defineConfig } from "prisma/config";

config();
if (process.env.PRISMA_USE_TEST_URL === "1") {
  config({ path: ".db-sync/sync.env" });
  if (!process.env.TEST_URL) throw new Error("缺少 TEST_URL");
  const testUrl = new URL(process.env.TEST_URL);
  if (testUrl.hostname === "host.docker.internal") testUrl.hostname = "localhost";
  process.env.DATABASE_URL = testUrl.toString();
}

export default defineConfig({
  schema: "prisma/schema",
  migrations: {
    path: "prisma/migrations",
    seed: "tsx prisma/seed.ts",
  },
  datasource: {
    url: process.env["DATABASE_URL"],
  },
});
